package blockbranch.realistic;
import java.util.*;
public final class SnowyTaigaCheck{
 static int at(int[]a,int x,int y,int z){int k=((y-TerrainShape.FLOOR)<<8)|((z&15)*16+(x&15));for(int v:a)if((v>>>blockbranch.cubic.CanopyLayer.STATE_BITS)==k)return v&blockbranch.cubic.CanopyLayer.STATE_MASK;return 0;}
 public static void main(String[]args){for(long seed:new long[]{424242,1,-17}){var d=new DrainageNetwork(new TerrainShape(seed),seed);var c=new ClimateField(seed);var e=new GroundEcology.Field(d::sample,c);var p=blockbranch.realistic.SnowyTaigaFixtures.fixture(d,seed);int snow=0,roof=0;int cx=p.x()>>4,cz=p.z()>>4;for(int z=cz-1;z<=cz+1;z++)for(int x=cx-1;x<=cx+1;x++){var base=SwampCanopy.merge(WoodlandTrees.column(seed,x,z,d,c),MangroveTrees.column(seed,x,z,d,c));var a=SnowyTaiga.snowColumn(seed,x,z,base,d,c,e);require(a.length<8192&&Arrays.equals(a,SnowyTaiga.snowColumn(seed,x,z,base,d,c,e)),"Bounded deterministic world snow");for(int v:a){int k=v>>>blockbranch.cubic.CanopyLayer.STATE_BITS,code=v&blockbranch.cubic.CanopyLayer.STATE_MASK;if(!SnowyTaiga.snow(code))continue;snow++;int wx=x*16+(k&15),wz=z*16+((k>>>4)&15),y=(k>>>8)+TerrainShape.FLOOR;var s=d.sample(wx,wz);require(s.waterLevel()==DrainageNetwork.DRY&&s.height()<y&&d.channelAt(wx,wz).edge()<0,"No water/channel conversion or buried snow");if(y>s.height()+1){roof++;int below=at(base,wx,y-1,wz);require(WoodlandTrees.logCode(below)||below>=7&&below<=45,"Crown snow rests on actual solid canopy");}}}require(snow>100&&roof>50,"Actual ground and crown snow");require(!Taiga.contains(seed,p.x(),p.z(),d,c)&&SnowyTaiga.contains(seed,p.x(),p.z(),d,c),"Disjoint cold-forest identity");System.out.println("SNOWY_TAIGA seed="+seed+" point="+p+" snow="+snow+" crownSnow="+roof);}
 System.out.println("SNOWY_TAIGA_DRY_DOMAIN_SUPPORT_DETERMINISM_PASS");}
 static void require(boolean b,String m){if(!b)throw new AssertionError(m);}
}
